        "aiShortRec":  "พบ 5 ไซต์บ้านหรูพรีเมียม Active จริงใน จ.อุดรธานี (อ.เมือง, อ.กุดจับ) ยอดสั่งซื้อ SCG โตก้าวกระโดด ฿3.39M (+116% YoY)",
        "aiRecommendation":  "ลูกค้าระดับ Star Growth (10482913) พันธมิตร VIP ร้านคู่ยงฮวด ช่างเปิดรับทีมเทคนิค SCG เข้าแนะนำปูนเสือ สกิมโค้ทและหลังคา SCG Prestige แนะนำต่อยอด Total Solution ด่วน",
        "customDiagnostic":  "บริษัทรับสร้างบ้านพรีเมียมสไตล์ Modern Classic Luxury (งบ 3-15 ล้านบาท) ที่มียอดสั่งซื้อ SCG ปี 2026 เติบโตก้าวกระโดดสูงถึง \u003cstrong\u003e฿3,396,188 (+116.3% YoY)\u003c/strong\u003e เป็นลูกค้าระดับ VIP ของร้านผู้แทนจำหน่าย SCG \u0027คู่ยงฮวด\u0027 และมีความร่วมมือเปิดรับทีมเทคนิค SCG เข้าสาธิตการใช้งานปูนเสือ สกิมโค้ท และระบบหลังคา SCG Prestige ถึงหน้างานจริง มีงานสร้างบ้านหรูและคฤหาสน์ 800 ตร.ม. กระจายตัวทั่ว จ.อุดรธานี",
        "customRecommendations":  [
                                      "\u003cstrong\u003eระบบหลังคาคอนกรีต SCG Prestige \u0026 อุปกรณ์ครอบแห้ง Dry-Tech:\u003c/strong\u003e ล็อกสเปกหลังคา SCG Prestige คู่แผ่นสะท้อนความร้อน Ultra Cool และฉนวน STAY COOL เป็นมาตรฐานสำหรับบ้าน Modern Classic ทุกหลัง",
                                      "\u003cstrong\u003eปูนเสือ สกิมโค้ท (Tiger Skim Coat) \u0026 ปูนฉาบละเอียด:\u003c/strong\u003e ต่อยอดความสำเร็จจากไซต์สาธิต อ.กุดจับ สู่การทำสัญญาเหมาปูนเสือ สกิมโค้ทและปูนเสือ มอร์ตาร์ สำหรับทุกไซต์งานใน อ.เมือง และ อ.กุดจับ",
                                      "\u003cstrong\u003eคอนกรีตผสมเสร็จ CPAC 240-280 ksc \u0026 เหล็กข้ออ้อย SD40 SCG:\u003c/strong\u003e นำเสนอคอนกรีต CPAC และเหล็ก SCG สำหรับงานโครงสร้างคฤหาสน์ 800 ตร.ม. และบ้านพักอาศัยทุกหลัง",
                                      "\u003cstrong\u003eชุดสุขภัณฑ์และก๊อกน้ำ COTTO Touchless \u0026 กระเบื้อง COTTO:\u003c/strong\u003e นำเสนอสุขภัณฑ์ประหยัดน้ำ กระเบื้องหินอ่อน COTTO และอุปกรณ์ห้องน้ำเกรดพรีเมียม ตอบโจทย์บ้านเดี่ยวระดับ 3-15 ล้านบาท"
                                  ],
