        "customDiagnostic":  "ห้างหุ้นส่วนจำกัด หล้าก่ำ ทรัพย์เจริญยิ่ง (Larkam Engineering) เป็นบัญชีที่มีความเสี่ยงสูญเสียรายได้ระดับสีแดง (Red Alert) เนื่องจากมียอดซื้อสินค้า SCG ในปี 2026 ลดลงเหลือเพียง \u003cstrong\u003e฿18,166 (-83.6% YoY)\u003c/strong\u003e จาก ฿110.5K ในปี 2025 (SCG Code 10126345) ทั้งที่มีการเซ็นสัญญาและยกเสาเอกเปิดไซต์ใหม่ใน จ.อุดรธานี พร้อมกันถึง 3 หลัง (บ้านคุณเรืองเดช อ.หนองหาน ยกเสาเอก 9/9/69, บ้านคุณบุญธรรม อ.ประจักษ์ฯ, บ้านคุณฉกรรจ์ อ.ไชยวาน) แสดงว่าหลุดไปซื้อปูนและคอนกรีตแบรนด์คู่แข่งหน้างาน ถือเป็นจังหวะทองที่ทีมขาย SCG ต้องเร่งเสนอราคาพิเศษ CPAC เพื่อชิงสเปกกลับมาเต็มจำนวน",
